-- 169_school_intro_backfill_round2.sql
-- 院校简介回填（第 169 批，2026-11-24）：第二批 12 所「官网可查、简介为空」院校。
--
-- 口径同 168：只用院校官网自述页原文，逐字摘录，200-500 字，句末截断；
-- 仅当 intro 为空时更新，重复执行不覆盖既有简介；不物理删除。
-- 证据：backfill_local/out/school_intro_169_evidence.csv
--
-- 本批说明：部分站点正文把数字拆成独立短行，抓取时改为全行拼接，避免「始建于年」类丢字；
-- 已逐条复核数字与句子完整性。
--
-- 仍未处理（下轮候选，原因）：
--   #25/#26/#202/#264/#536 机械总院各所：官网统一跳转到集团站（www.riamb.ac.cn 集团简介），
--     站内无各所独立简介，避免混入集团/他所内容；
--   #30 中国北方车辆研究所：站内仅「汽检所简介」，无本所简介；
--   #163 山西大同大学：学校概况页 403；#834 北京警察学院：503；
--   #591 汕头大学：xxgk.htm 仅导航壳，正文未渲染；
--   #641/#653/#711/#789/#842/#1006/#1035/#1039/#1062 等：首页或简介页为 JS/WAF 挑战壳；
--   #715/#722：页面自带「…」截断；#830/#844/#926/#885：官网无独立简介页或仅新闻流；
--   #780/#897/#1034/#1065：官网当前不可达。

UPDATE kaoyan_schools AS s
SET intro = v.intro,
    updated_at = now()
FROM (VALUES
    (40, '1956年6月，根据毛主席关于财政部要加强财政经济问题研究的指示，财政部财政科学研究所正式成立，2016年2月更名为中国财政科学研究院。2023年2月，成为金砖财金智库网络中方牵头智库、东盟与中日韩(10+3)财金智库网络中方牵头智库之一。财科院设有研究生院（副司级)，为国家培养财政、会计高端专业人才，专门从事研究生教育管理工作。1978年成为国务院学位委员会和教育部批准的首批硕士研究生招收单位，开始招收硕士研究生，1982年成为国家首批博士学位授予单位，1983年开始招收博士研究生，并创办了我国首个会计电算化博士点。2004年成为国务院学位委员会和教育部批准的首批会计硕士专业学位(MPAcc)试点单位之一。2012年获得审计硕士专业学位(MAud)授予权。2018年获得税务硕士专业学位(MT)授予权。2018年3月2日，中国财政科学研究院研究生部宣布更名为中国财政科学研究院研究生院，标志着研究生教育工作进入了一个崭新的发展时期。“科研教学相长，理论实践互通”，经过40余年的发展，财科院成功地把研究生教育与政策研究、智库建设紧密结合。'),
    (206, '航空工业气动院始建于1955年，隶属于中国航空工业集团有限公司中国航空研究院，是航空工业唯一的空气动力专业研究机构，教育部首批授权流体力学硕士培养单位，设有博士后科研工作站，位于辽宁沈阳、黑龙江哈尔滨、江苏溧阳。伴随着中国航空工业的成长与发展，气动院参与了几乎所有重点飞机型号的研制工作，被评为“航空工业重大贡献单位”。这里拥有四个省部级重点实验室、几十个科研创新团队，已建成以亚洲最大连续式跨声速风洞为代表的亚、跨、超及高超声速风洞群，以亚洲唯一低速增压风洞、8mx6m回流式大型风洞为代表的低速风洞群和3300万亿次/秒的高性能计算集群，为各类航空航天飞行器、高铁、汽车、建筑以及风电等行业提供高、低速气动力综合技术服务和解决方案。气动院2021年成立的南方分院位于江苏省溧阳市，面向国家工业空气动力学创新发展需求，建设工业空气动力学研究与产业创新高地，为大飞机、直升机、汽车、高铁等领域提供实验检测与综合技术解决方案。'),
    (261, '黑龙江省中医药科学院的前身是成立于1957年的黑龙江省祖国医药研究所（俗称“祖研”），1995年加挂“黑龙江省中医医院”牌匾，2013年正式更名为黑龙江省中医药科学院。是黑龙江省中医药管理局直属的集科研、医疗、教育、产业和文化五位一体的综合性中医药研究机构。我院现建筑面积13万平方米，分为三辅、香安、南岗3个院区，下设7个研究所、1个制药厂、1个研究生院、2个杂志社编辑部（《中国中医药科技》《黑龙江省中医药》），2个社区卫生服务中心，1个国家中药剂型改革基地和25个专病教研室，国家中医（肿瘤）区域医疗中心（中国中医科学院广安门医院黑龙江医院）和中医疫病防治基地项目即将投入使用。我院先后三次荣获“全国卫生系统先进集体”荣誉称号，并被省委省政府评为推进“八大经济区”和“十大工程”建设先进单位荣誉称号、被授予“贡献奖”，是全省卫生系统唯一受表彰单位，2021年被授予“省直文明单位”荣誉称号。我院现有员工1557人，其中卫生专业技术人员1267人，正、副高级职称专家385人。'),
    (508, '中国船舶集团有限公司第七二五研究所(以下简称“七二五所”)成立于1961年，隶属中国船舶集团有限公司，专业从事舰船材料与工艺及应用性研究。七二五所(事业单位)开办资金5307万元，(企业营业执照)注册资金81599万元。科研方面：涉及船体结构材料、有色金属材料、非金属材料、腐蚀与防护技术、特种材料、焊接工艺、自然环境试验等多个重点领域。目前,七二五所拥有海洋腐蚀与防护全国重点实验室等8个国家级创新平台、4个海洋环境试验站、4个国家级检测认证中心、25个省部级及6个市级创新平台;并拥有材料学和材料加工工程硕士学位授权点、材料学博士学位授权点和博士后工作站。科技产业方面：七二五所秉承“精诚团结、求实创新、志存高远、追求卓越”的精神，致力于构建“国内领先、国际一流的集科研和多个高技术产业为一体的高科技产业集团”，持续推进科技成果转化和高新技术产业化，初步建成了领先的高科技产业集团。主要产品有：金属波纹管膨胀节、特种材料压力容器、管道和桥梁支座、特种材料铸锻件、特种焊接材料、金属爆炸复合材料、钛合金构件和铸件、海绵钛、防腐防污产品、非金属材料制品、风电叶片、船舶压载水系统、海水淡化系统等。'),
    (576, '长沙学院创建于1970年，办学源头可追溯至1970年11月的长沙市革委会师训班、1978年7月的长沙基础大学、1983年5月的长沙大学。2004年由原长沙大学（专科）升格为全日制公办本科院校，实行“省市共建共管、以长沙市为主管理”体制。学校是硕士学位授予单位，国家“十三五”产教融合发展工程应用型本科规划高校，全国高校实践育人创新创业示范基地，湖南省“双一流”高水平应用特色学院，湖南省一本招生高校，湖南省文明高校。学校始终坚守为党育人、为国育才的初心使命，秉承“力学笃行”的校训，弘扬“崇德求真，实干担当”的长大精神，坚持“立足长沙、面向湖南、辐射全国”的服务定位，着力服务支撑湖南实现“三高四新”美好蓝图，致力于建成特色鲜明的高水平应用型地方大学。2026软科中国大学排名中，学校位列全国1300余所本科高校第328位。学校坐落于世界“媒体艺术之都”、中国历史文化名城、长江中游地区重要中心城市、省会级特大城市——长沙，位于国家级文化产业示范园区、国家文化和科技融合示范基地——马栏山视频文创园核心功能区内。'),
    (745, '西安美术学院建校于1949年，其前身为西北人民艺术学院二分部，1949年7月由山西临汾迁至西安市长安县，更名为西北军政大学艺术学院，后历经西北艺术专科学校、西北美术专科学校等阶段，于1960年5月正式定名为西安美术学院，1994年学院整体迁至西安市雁塔区含光路南段。西安美术学院自建校以来，广纳贤才、汇聚名师，立足卓绝的延安精神和厚重的历史文化传统，传承红色基因，形成了独具特色的艺术教育理念，为国家的建设发展培养了大批优秀艺术人才，创作了许多在中国当代美术史上具有深远影响的作品，为繁荣社会主义艺术事业做出了重要贡献，产生了良好的社会声誉和影响。改革开放以来，西安美术学院以育人为根本、以教学为中心、以教师为主体、以质量为生命、以繁荣文化为己任、秉承“艰苦创业，追求卓越”的精神，恪守“弘美厚德，借古开今”的校训，发挥地域优势，突出西部特色，率先将书法和民间美术纳入课堂教学，长期坚持并重视周秦汉唐历史文化、延安革命文艺、西北民族民间艺术、当代“长安画派”与“黄土画派”四大传统和绘画、书法、美术史论、中国民间美术“四大基础”教学，逐渐形成了基础雄厚、结构合理、特色鲜明的美术教育体系。'),
    (837, '天津中德应用技术大学是国内第一所应用技术大学，隶属于天津市人民政府管理，由天津市工业和信息化局举办，接受天津市教育委员会业务指导。学校始于我国与德国、日本、西班牙三国政府在职业教育领域最大的合作项目，由原天津中德现代工业技术培训中心、原天津企业管理培训中心合并组建而成。1985年建校即开始企业员工培训；2001年改制为天津中德职业技术学院；2015年升格为天津中德应用技术大学；2017年被纳入天津市“双一流”大学建设体系；2021年获批“硕士学位授予单位”。学校秉承“崇实 求精 致良知”的校训精神，坚持聚焦工业发展需求，致力于培养“政治过硬、技能精湛、诚实守信、理性平和”的高级技师、一线工程师、大国工匠，形成了“以工匠精神为传承、以实践能力为核心、以产教融合为路径”的办学特色。学校占地725.4亩，建筑面积35.95万平方米。建有校内实验实训室88个，教学科研仪器设备总值5亿余元人民币；拥有省部级科研平台4个、省部级科普基地3个、校内专门研究机构2个、与企业共建校内技术创新中心及联合重点实验室等科研平台15个。'),
    (860, '太原学院是山西省人民政府领导、太原市人民政府管理、山西省教育厅业务指导的全日制普通本科院校。学校前身为2002年12月由原太原大学、太原师范学校、太原市教育学院合并组建的新太原大学，2013年4月经教育部批准升格为全日制综合类普通本科院校，更名为太原学院，2017年获得学士学位授予权，2022年成为山西省首批应用型本科高校建设单位，2023年9月顺利通过教育部本科教学工作合格评估，人才培养质量和办学水平实现整体跨越，迈入加快建设省内一流应用型本科高校的新阶段。学校地处三晋古都、山西省省会太原，由汾东、滨河、府东三个校区组成。主校区汾东校区位于山西中部城市群、太原都市圈和山西省转型综合改革示范区的核心区域，信息畅达、交通便利。学校占地1681亩，校舍建筑面积47.77万平方米，教学科研仪器设备总值1.76亿元，馆藏纸质图书172万册、电子图书122.2万册，面向全国31个省（自治区、直辖市）招生，现有全日制在校学生1.6万余人。'),
    (861, '山西警察学院前身为1949年成立的山西省公安学校，1981年组建山西省人民警察学校，2000年3月经教育部批准成立山西警官高等专科学校，2016年3月教育部批准山西警官高等专科学校升格为本科层次普通高校，更名为山西警察学院。学院2020年5月增列为学士学位授权单位，目前已建成 “公安部爆炸物品公共安全教育训练基地”、“国家文物局文博人才培训示范基地”、“全国公安民警心理训练山西实验中心”和“山西公安民警培训基地”。学院是经国家教育部批准设立、山西省人民政府举办的普通高等学校，主管部门是山西省公安厅，接受山西省教育厅业务指导和管理。学院内设机构35个，其中党政管理机构（含群团组织）18个，教学科研机构12个，教辅机构5个。学院现有3个校区，占地面积884.58亩，总建筑面积28.8万平方米，教学行政用房11.01万平方米，教学科研仪器设备总值5005万元。图书馆建筑面积1.4万平方米，纸质图书80万册。建有校内实验实训场所83个，在全省建有战教融合基地、教学基地、实践基地共60个。'),
    (930, '淮南师范学院是安徽省属全日制普通高等本科院校，前身为淮南师范专科学校，始建于1958年。1999年，淮南师范专科学校、淮南教育学院、淮南师范学校三校合并组建成新的淮南师范专科学校。2000年，教育部批准淮南师范专科学校升格为本科层次的淮南师范学院。2024年，被确立为安徽省重点立项建设硕士学位授予单位，获批立项为安徽省首批应用特色高校培育单位。学校2007年顺利通过了教育部组织的本科教学工作水平评估，2009年在安徽省新建本科高校中率先被确定为硕士研究生培养省级立项建设单位，2018年接受了教育部本科教学工作审核评估。2021年，英语、生物科学2个专业率先进入普通高校本科第一批次招生，化学等9个师范专业，计算机科学与技术等11个非师范专业实现第一批次招生。学校现有2个校区，占地76.79万平方米，建筑总面积62.35万平方米，教科研仪器设备总值2.62亿元，馆藏图书316万册（含电子图书）。'),
    (1011, '广东警官学院前身是广东省公安干部学校，创办于1949年11月，2004年5月经教育部批准设立“广东警官学院”。学校主管部门是广东省公安厅，教育教学业务主管部门是广东省教育厅。2008年获批学士学位授予权。2012年通过教育部本科教学合格评估。2018年获评广东省依法治校示范校。2019年通过教育部本科教学工作审核评估。2025年通过教育部新一轮本科教育教学工作审核评估。2021年成为硕士学位授予立项建设单位。在76年的办学实践中，学校始终坚持服务政法公安工作和经济社会发展，充分发挥公安专门人才培养基地和公安智库的作用，构建了具有广东公安特色的教育培训体系。学校以“忠诚勇毅、博雅致用”为校训，以“公正严明、笃学敏行”为校风，以“博文约礼、厚生善导”为教风，以“乐学慎思、允文允武”为学风，形成了政治建校、警务化管理、校局合作协同育人、实战化教学等鲜明的办学特色。学校建有嘉禾、滨江两个校区，占地面积共373796平方米。其中，主校区为嘉禾校区，主要承担全日制本科生教育任务；滨江校区主要承担民警培训和成人教育任务。两校区校舍总建筑面积25.47万平方米。'),
    (1027, '广西职业师范学院（原广西经济管理干部学院）坐落于广西首府南宁市风景秀丽的邕江之滨、相思湖畔，是自治区人民政府直属、自治区教育厅主管的公办全日制普通本科学校，致力于培养区域经济社会发展所需要的高素质应用型、技术技能型人才和职业教育师资。学校的前身为创建于1951年5月的广西省行政干部训练班。其后，为适应不同历史时期广西经济建设需要，学校历经了广西人民革命大学、广西行政干部学校、广西经济干部学校、广西经济管理干部学院等历史沿革，并于2019年6月经教育部批准设置为“广西职业师范学院”。在不同历史时期，学校聚焦“服务广西经济建设”发展主线，不忘建校初心、勇担办学使命，为广西经济建设和社会发展作出了不可磨灭的突出贡献，享有良好的办学声誉和广泛的社会影响。近年来，学校围绕“地方性、应用型、职师类”办学定位，落实“以本为本、应用为先、职师特色”办学思路，在服务地方产业转型升级和职业教育提质增效上取得显著成效。')
) AS v(id, intro)
WHERE s.id = v.id
  AND (s.intro IS NULL OR btrim(s.intro) = '');
